source = '''def transform(grid):
    h, w = len(grid), len(grid[0])
    # The seed consists of colored parallel diagonals. Pick the diagonal
    # direction in which every observed diagonal is monochromatic.
    candidates = []
    for kind in ("difference", "sum"):
        lines = {}
        conflicts = 0
        for r, row in enumerate(grid):
            for c, value in enumerate(row):
                if value == 0:
                    continue
                key = c - r if kind == "difference" else r + c
                if key in lines and lines[key] != value:
                    conflicts += 1
                else:
                    lines[key] = value
        candidates.append((conflicts, -len(lines), kind, lines))
    candidates.sort()
    _, _, kind, lines = candidates[0]
    offsets = []
    for r, row in enumerate(grid):
        for c, value in enumerate(row):
            if value:
                offsets.append((c - r if kind == "difference" else r + c, value))
    max_period = len(set(key for key, _ in offsets))
    palette = None
    period = None
    for p in range(1, max_period + 1):
        classes = {}
        valid = True
        for key, value in offsets:
            residue = key % p
            if residue in classes and classes[residue] != value:
                valid = False
                break
            classes[residue] = value
        if valid and len(classes) == p:
            period, palette = p, classes
            break
    if palette is None:
        # This path is not needed for the demonstrated task instances.
        period = max_period
        palette = {}
        for key, value in offsets:
            palette.setdefault(key % period, value)
    out = []
    for r in range(h):
        row = []
        for c in range(w):
            key = c - r if kind == "difference" else r + c
            row.append(palette[key % period])
        out.append(row)
    return out
'''
